#!/usr/bin/env python3
"""Fixture tests for scripts/check-gradle-locks.py."""

from __future__ import annotations

import contextlib
import importlib.util
import io
import shutil
import tempfile
from pathlib import Path

SCRIPTS = Path(__file__).resolve().parent
REAL_ANDROID = SCRIPTS.parent / "mobile/android"
spec = importlib.util.spec_from_file_location("check_gradle_locks", SCRIPTS / "check-gradle-locks.py")
assert spec and spec.loader
checker = importlib.util.module_from_spec(spec)
spec.loader.exec_module(checker)

HEADER = (
    "# This is a Gradle generated file for dependency locking.\n"
    "# Manual edits can break the build and are not advised.\n"
    "# This file is expected to be part of source control.\n"
)
GOOD_LOCK = HEADER + (
    "androidx.annotation:annotation:1.9.1=debugRuntimeClasspath,releaseRuntimeClasspath\n"
    "org.unifiedpush.android:connector:3.3.3=playReleaseRuntimeClasspath\n"
    "empty=annotationProcessor\n"
)
SHA_A = "a" * 64
GOOD_VERIFICATION = f"""<?xml version="1.0" encoding="UTF-8"?>
<verification-metadata xmlns="https://schema.gradle.org/dependency-verification">
   <configuration>
      <verify-metadata>true</verify-metadata>
      <verify-signatures>false</verify-signatures>
   </configuration>
   <components>
      <component group="androidx.annotation" name="annotation" version="1.9.1">
         <artifact name="annotation-1.9.1.jar">
            <sha256 value="{SHA_A}" origin="Generated by Gradle"/>
         </artifact>
      </component>
   </components>
</verification-metadata>
"""


def run(android: Path, *flags: str) -> tuple[int, str, str]:
    stdout, stderr = io.StringIO(), io.StringIO()
    with contextlib.redirect_stderr(stderr), contextlib.redirect_stdout(stdout):
        code = checker.main([str(android), *flags])
    return code, stdout.getvalue(), stderr.getvalue()


@contextlib.contextmanager
def android_copy():
    with tempfile.TemporaryDirectory() as temp:
        android = Path(temp) / "android"
        android.mkdir()
        shutil.copy2(REAL_ANDROID / "build.gradle.kts", android / "build.gradle.kts")
        yield android


def write(path: Path, text: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(text, encoding="utf-8")


def with_files(android: Path) -> None:
    write(android / "gradle/locks/app.lockfile", GOOD_LOCK)
    write(android / "gradle/verification-metadata.xml", GOOD_VERIFICATION)


def test_real_tree_wiring_passes_and_reports_missing_files() -> None:
    code, out, err = run(REAL_ANDROID)
    assert code == 0, err
    assert "not generated yet" in out, out


def test_release_check_refuses_missing_files() -> None:
    code, _, err = run(REAL_ANDROID, "--require-files")
    assert code == 1, err
    assert "app.lockfile not generated yet" in err and "verification-metadata.xml not generated yet" in err, err


def test_complete_files_pass_even_when_required() -> None:
    with android_copy() as android:
        with_files(android)
        code, out, err = run(android, "--require-files")
        assert code == 0, err
        assert "not generated" not in out, out


def test_removing_the_wiring_fails() -> None:
    cases = {
        "no allprojects": "subprojects { }\n",
        "no locking": "allprojects { repositories { google() } }\n",
        "locking outside allprojects": "allprojects { }\ndependencyLocking { lockAllConfigurations() }\n",
        "lock file not redirected": "allprojects { dependencyLocking { lockAllConfigurations() } }\n",
        "locking only in a comment": "allprojects {\n // dependencyLocking { lockAllConfigurations() }\n}\n",
        "lenient": (
            "allprojects { dependencyLocking { lockAllConfigurations()\n"
            "lockMode.set(LockMode.LENIENT)\n"
            'lockFile.set(file("gradle/locks/x.lockfile")) } }\n'
        ),
    }
    for name, text in cases.items():
        with android_copy() as android:
            write(android / "build.gradle.kts", text)
            code, _, err = run(android)
            assert code == 1, (name, err)


def test_malformed_lockfiles_fail() -> None:
    bad = {
        "no header": "androidx.annotation:annotation:1.9.1=debugRuntimeClasspath\n",
        "dynamic version": HEADER + "com.example:lib:1.+=debugRuntimeClasspath\n",
        "range": HEADER + "com.example:lib:[1.0,2.0)=debugRuntimeClasspath\n",
        "latest": HEADER + "com.example:lib:latest.release=debugRuntimeClasspath\n",
        "snapshot": HEADER + "com.example:lib:1.0-SNAPSHOT=debugRuntimeClasspath\n",
        "duplicate": HEADER + "a:b:1=x\na:b:1=y\n",
        "garbage": HEADER + "not a lock entry\n",
        "empty file": "",
    }
    for name, text in bad.items():
        with android_copy() as android:
            with_files(android)
            write(android / "gradle/locks/app.lockfile", text)
            code, _, err = run(android)
            assert code == 1, (name, err)


def test_weak_verification_metadata_fails() -> None:
    bad = {
        "verification off": GOOD_VERIFICATION.replace("<verify-metadata>true", "<verify-metadata>false"),
        "md5 only": GOOD_VERIFICATION.replace(f'<sha256 value="{SHA_A}"', f'<md5 value="{"b" * 32}"').replace(
            'origin="Generated by Gradle"/>', 'origin="x"/>'
        ),
        "short sha": GOOD_VERIFICATION.replace(SHA_A, "abc"),
        "no components": GOOD_VERIFICATION.split("<components>")[0] + "<components></components></verification-metadata>",
        "regex trust": GOOD_VERIFICATION.replace(
            "<verify-signatures>false</verify-signatures>",
            '<verify-signatures>false</verify-signatures>\n<trusted-artifacts><trust group=".*" regex="true"/></trusted-artifacts>',
        ),
        "not xml": "<verification-metadata>",
        "wrong root": "<foo/>",
    }
    for name, text in bad.items():
        with android_copy() as android:
            with_files(android)
            write(android / "gradle/verification-metadata.xml", text)
            code, _, err = run(android)
            assert code == 1, (name, err)


def test_missing_android_dir_fails_closed() -> None:
    assert run(Path("/nonexistent-android-dir"))[0] == 1
    assert run(REAL_ANDROID, "extra", "--require-files")[0] == 2


if __name__ == "__main__":
    test_real_tree_wiring_passes_and_reports_missing_files()
    test_release_check_refuses_missing_files()
    test_complete_files_pass_even_when_required()
    test_removing_the_wiring_fails()
    test_malformed_lockfiles_fail()
    test_weak_verification_metadata_fails()
    test_missing_android_dir_fails_closed()
    print("Gradle lock fixture tests passed")
